PhoneBook <- setRefClass("PhoneBook",
  fields = list(entries = "list"),
  methods = list(
    add = function(name, number) {
      status <- if (name %in% names(entries)) "수정" else "추가"
      entries[[name]] <<- number
      status
    },
    find = function(name) {
      if (name %in% names(entries)) entries[[name]] else "없음"
    },
    remove = function(name) {
      if (name %in% names(entries)) {
        entries[[name]] <<- NULL
        TRUE
      } else FALSE
    },
    names_sorted = function() {
      sort(names(entries))
    }
  )
)
